function sumOfSquares(nums) {
  const n = nums.length;
  const divisors = [];
  for (let d = n; d >= 1; d--) {
    let k = 0;
    while (k * d < n) k++;
    if (k * d === n) divisors.push(d);
  }
  return divisors.reduce((sum, d) => sum + nums[d - 1] ** 2, 0);
}

